let lang='zh',dialogue=false;try{const saved=localStorage.getItem('sd.lang');if(['zh','en'].includes(saved))lang=saved;}catch{}
const root=document.querySelector('#content'),sourceBase='https://raw.githubusercontent.com/storyloveai/ocai/refs/heads/codex/coastal-vn-art-pilot/ooc-replica/art-concepts/coastal-vn/2026-11-04/source/';
function draw(){const c=copy[lang];document.documentElement.lang=lang;document.title=c.title+' · StoryDate';document.querySelectorAll('[data-lang]').forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.lang===lang)));root.classList.toggle('show-dialogue',dialogue);root.innerHTML=`<div class="eyebrow">${c.tag}</div><h1>${c.title}</h1><p>${c.lead}</p><div class="toolbar"><button data-dialogue aria-pressed="${dialogue}">${dialogue?c.plain:c.test}</button><a href="https://github.com/storyloveai/ocai/issues/112" target="_blank" rel="noopener">${c.issue}</a></div>${[['cinema-exterior-a',c.one,c.noteOne],['cinema-auditorium-a',c.two,c.noteTwo]].map(([id,title,note])=>`<article><div class="label"><h2>${title}</h2><span>1672 × 941 · ${c.tag}</span></div><div class="frame"><img src="/assets/art-review/coastal-vn/${id}.webp" width="1672" height="941" alt="${title}"><div class="dialogue"><b>${c.layout}</b><p>${c.layoutText}</p></div></div><div class="caption"><p>${note}</p><a href="${sourceBase+id}.png" target="_blank" rel="noopener">${c.source}</a></div></article>`).join('')}<section class="next"><h2>${c.next}</h2><p>${c.nextText}</p><p>${c.limitation}</p></section>`;root.querySelector('[data-dialogue]').onclick=()=>{dialogue=!dialogue;draw();};}
document.querySelectorAll('[data-lang]').forEach(b=>b.onclick=()=>{lang=b.dataset.lang;try{localStorage.setItem('sd.lang',lang);}catch{}draw();});draw();
